    private static BigInteger modularInverse(BigInteger a, BigInteger p) {
        BigInteger[] result = extendedGCD(a, p);
        BigInteger gcd = result[0];
        BigInteger x = result[1];
        if (!gcd.equals(BigInteger.ONE)) {
