    private static BigInteger[] extendedGCD(BigInteger a, BigInteger b) {
        if (a.equals(BigInteger.ZERO)) {
            return new BigInteger[]{b, BigInteger.ZERO, BigInteger.ONE};
        } else {
            BigInteger[] gcdResult = extendedGCD(b.mod(a), a);
            BigInteger g = gcdResult[0];
            BigInteger x = gcdResult[1];
            BigInteger y = gcdResult[2];

            return new BigInteger[]{g, y.subtract(b.divide(a).multiply(x)), x};
        }
    }
